<template><el-drawer v-model="visible" title="引用原文与版本" size="min(700px,95vw)" @closed="clear"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-loading="loading"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="文档">{{detail.title}}</el-descriptions-item><el-descriptions-item label="内容版本">{{detail.contentVersion}}</el-descriptions-item><el-descriptions-item label="位置">第 {{detail.page||'—'}} 页 · {{detail.anchor||'无锚点'}}</el-descriptions-item><el-descriptions-item v-if="detail.query" label="检索问题">{{detail.query}}</el-descriptions-item><el-descriptions-item v-if="detail.retrievalMode||detail.scoreType" label="检索模式">{{detail.retrievalMode||detail.scoreType}}</el-descriptions-item><el-descriptions-item v-if="detail.score!==undefined" label="检索分数">{{detail.score}}（{{detail.scoreType||'未返回类型'}}）</el-descriptions-item><el-descriptions-item v-if="detail.chunkId" label="命中分块">{{detail.chunkId}}</el-descriptions-item><el-descriptions-item label="引用核验">{{(detail.verification?.supported??detail.verified)===true?'已核验':(detail.verification?.supported??detail.verified)===false?'核验未通过':'未执行核验'}}</el-descriptions-item></el-descriptions><h3>命中片段原文</h3><pre class="ps-pre">{{detail.matchedChunkText||detail.text||'当前没有返回原文'}}</pre><template v-if="detail.evidenceSnippet"><h3>证据摘要片段</h3><pre class="ps-pre">{{detail.evidenceSnippet}}</pre></template><template v-if="detail.parentContext"><h3>原文父块上下文</h3><p class="ps-muted">父块 {{detail.parentKey||'未返回标识'}}，引用定位仍以命中片段为准。</p><pre class="ps-pre">{{detail.parentContext}}</pre></template><template v-if="detail.context"><h3>生成说明</h3><pre class="ps-pre">{{detail.context}}</pre></template><el-button v-hasPermi="['paismart:document:read']" type="primary" @click="previewDocument">查看文档对应页</el-button></template></div><DocumentPreview v-model="documentOpen" :document="document" :initial-page="detail?.page" :initial-anchor="detail?.text||detail?.anchor"/></el-drawer></template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { getDocument, getReference } from '@/api/paismart/documents'
import type { Document, Reference } from '@/types/paismart'
import DocumentPreview from '../../documents/components/DocumentPreview.vue'
import { errorText } from '../../composables/usePage'
const props=defineProps<{modelValue:boolean;reference?:Reference}>(),emit=defineEmits<{ 'update:modelValue':[boolean] }>()
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),detail=shallowRef<Reference>(),document=shallowRef<Document>(),documentOpen=ref(false),loading=ref(false),error=ref('')
let controller:AbortController|undefined,serial=0,previewSerial=0
function clear(){serial++;previewSerial++;controller?.abort();controller=undefined;detail.value=undefined;document.value=undefined;documentOpen.value=false;error.value='';loading.value=false}
async function load(){const original=props.reference?{...props.reference}:undefined;clear();if(!original)return;const current=serial,requestController=new AbortController();controller=requestController;loading.value=true;try{const response=await getReference(original.id,requestController.signal);if(current===serial&&props.modelValue){detail.value=String(original.documentId)===String(response.data.documentId)&&String(original.contentVersion)===String(response.data.contentVersion)?{...original,...response.data}:response.data}}catch(e){if(current===serial&&!requestController.signal.aborted)error.value=errorText(e)}finally{if(current===serial)loading.value=false}}
async function previewDocument(){if(!props.modelValue||!detail.value)return;const reference={...detail.value},current=serial,request=++previewSerial;const isCurrent=()=>current===serial&&request===previewSerial&&props.modelValue;error.value='';try{const data=(await getDocument(reference.documentId)).data;if(!isCurrent())return;if(String(data.id)!==String(reference.documentId))throw new Error('返回文档与当前引用不一致');if(String(data.contentVersion)!==String(reference.contentVersion))throw new Error('当前文档版本与历史引用不同，不能用新版本冒充原引用');document.value=data;documentOpen.value=true}catch(e){if(isCurrent())error.value=errorText(e)}}
watch(()=>[props.modelValue,props.reference?.id],()=>{if(props.modelValue)void load();else clear()});onBeforeUnmount(clear)
</script>
